//! Block-entity data produced by the 26.3 tree beehive decorator.
use anyhow::{Result, ensure};
use native_persistence::{
    edit::{BlockEntityMutation, ChunkDraft},
    nbt::{Tag, TagType},
};

/// A nest containing the bees generated by a tree decorator.
#[derive(Clone, Debug)]
pub struct GeneratedBeeNest {
    pub position: [i32; 3],
    ticks: Vec<i32>,
}

impl GeneratedBeeNest {
    pub fn new(position: [i32; 3], ticks: Vec<i32>) -> Result<Self> {
        ensure!(
            (2..=3).contains(&ticks.len()),
            "invalid generated bee count"
        );
        ensure!(
            ticks.iter().all(|v| (0..599).contains(v)),
            "invalid generated bee ticks"
        );
        Ok(Self { position, ticks })
    }

    /// Full block-entity NBT suitable for a 26.3 chunk.
    pub fn block_entity(&self) -> Tag {
        let [x, y, z] = self.position;
        let bees = self
            .ticks
            .iter()
            .map(|ticks| {
                Tag::Compound(vec![
                    (
                        "entity_data".into(),
                        Tag::Compound(vec![("id".into(), Tag::String("minecraft:bee".into()))]),
                    ),
                    ("ticks_in_hive".into(), Tag::Int(*ticks)),
                    ("min_ticks_in_hive".into(), Tag::Int(600)),
                ])
            })
            .collect();
        Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:beehive".into())),
            ("x".into(), Tag::Int(x)),
            ("y".into(), Tag::Int(y)),
            ("z".into(), Tag::Int(z)),
            (
                "bees".into(),
                Tag::List {
                    element_type: TagType::Compound,
                    values: bees,
                },
            ),
            ("components".into(), Tag::Compound(Vec::new())),
        ])
    }

    /// Stage the entity without replacing existing data at the same position.
    pub fn stage_block_entity(&self, draft: &mut ChunkDraft) -> Result<()> {
        draft.stage_block_entity_mutations(&[BlockEntityMutation {
            expected: None,
            replacement: Some(self.block_entity()),
        }])
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use native_persistence::{edit::draft_chunk_blocks, nbt::NamedTag, world::ChunkPos};
    #[test]
    fn rejects_data_a_tree_decorator_cannot_generate() {
        assert!(GeneratedBeeNest::new([0; 3], vec![0]).is_err());
        assert!(GeneratedBeeNest::new([0; 3], vec![0, 599]).is_err());
        assert!(GeneratedBeeNest::new([0; 3], vec![-1, 1]).is_err());
        assert!(GeneratedBeeNest::new([0; 3], vec![0, 598, 1]).is_ok());
    }

    #[test]
    fn stages_generated_entity_without_replacing_existing_data() {
        let source = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("xPos".into(), Tag::Int(-1)),
                ("zPos".into(), Tag::Int(2)),
                ("Status".into(), Tag::String("minecraft:full".into())),
                (
                    "sections".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![],
                    },
                ),
            ]),
        };
        let mut draft = draft_chunk_blocks(&source, ChunkPos { x: -1, z: 2 }, &[]).unwrap();
        let nest = GeneratedBeeNest::new([-15, 64, 32], vec![0, 598]).unwrap();
        nest.stage_block_entity(&mut draft).unwrap();
        let Some(Tag::List { values, .. }) = draft.document().value.get("block_entities") else {
            panic!("missing block entities")
        };
        assert_eq!(values, &vec![nest.block_entity()]);
        let before = draft.document().clone();
        assert!(nest.stage_block_entity(&mut draft).is_err());
        assert_eq!(&before, draft.document());
        assert!(
            GeneratedBeeNest::new([0, 64, 32], vec![0, 1])
                .unwrap()
                .stage_block_entity(&mut draft)
                .is_err()
        );
        assert_eq!(&before, draft.document());
    }
}
